update test_questions set question=$q$Which nursing priority is most appropriate for a young male smoker with bilateral limb ischemia suggestive of Buerger's disease (TAO)?$q$, options=$o$[{"id": "a", "text": "Pulse and color trends are not relevant to TAO progression."}, {"id": "b", "text": "Gangrene monitoring is low priority."}, {"id": "c", "text": "Stop all tobacco use and monitor for gangrene progression."}, {"id": "d", "text": "Smoking cessation can wait until tissue loss occurs."}]$o$::jsonb where id=2228;
update test_questions set question=$q$Which teaching priority is most important for a client with Buerger's disease (TAO)?$q$, options=$o$[{"id": "a", "text": "Complete tobacco cessation is the key to limb preservation."}, {"id": "b", "text": "Pulse and color trends are not relevant to TAO progression."}, {"id": "c", "text": "Smoking cessation is optional in TAO."}, {"id": "d", "text": "Cessation counseling can be deferred until after tissue loss occurs."}]$o$::jsonb where id=2253;
